window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-09-03","title":"Portfolio Management: An Overview","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[131,168],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[107,117],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[85,126],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-03-LOS01","learning_goal_vi":"Mô tả phương pháp đầu tư theo danh mục.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01","F01-02"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":137},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":107},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":87}},"missing_items":[]},{"los_id":"CFA26-09-03-LOS02","learning_goal_vi":"Mô tả các bước của quy trình quản lý danh mục.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05"],"formula_ids":["F02-01","F02-02"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":142},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":108},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":95}},"missing_items":[]},{"los_id":"CFA26-09-03-LOS03","learning_goal_vi":"Mô tả các nhóm nhà đầu tư và nhu cầu đặc trưng.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":146},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":109},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":99}},"missing_items":[]},{"los_id":"CFA26-09-03-LOS04","learning_goal_vi":"Mô tả và phân biệt defined contribution với defined benefit pension plans.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05"],"formula_ids":["F04-01"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":148},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":110},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":101}},"missing_items":[]},{"los_id":"CFA26-09-03-LOS05","learning_goal_vi":"Mô tả các đặc điểm của ngành quản lý tài sản.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S05-01","S05-02","S05-03","S05-04"],"formula_ids":["F05-01","F05-02"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":152},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":111},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":117}},"missing_items":[]},{"los_id":"CFA26-09-03-LOS06","learning_goal_vi":"Mô tả mutual funds và so sánh với các pooled investment products.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S06-01","S06-02","S06-03","S06-04","S06-05"],"formula_ids":["F06-01","F06-02"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":158},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":112},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":110}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-03-LOS01"],"heading_vi":"Đánh giá đóng góp vào toàn danh mục","body_vi":"Portfolio approach không đánh giá từng khoản đầu tư riêng rẽ mà xem mức độ thay đổi expected return, total risk và concentration của toàn bộ tài sản sau khi thêm vị thế. Một cổ phiếu nhiều biến động vẫn có thể giảm tổng volatility nếu tương quan đủ thấp với holdings còn lại."},{"id":"S01-02","los_ids":["CFA26-09-03-LOS01"],"heading_vi":"Lợi ích của diversification","body_vi":"Kết hợp nguồn sinh lợi khác nhau giảm idiosyncratic risk và hạn chế tổn thất lớn tập trung ở một doanh nghiệp. Diversification không triệt tiêu systematic risk hoặc bảo đảm lãi trong khủng hoảng; cần xem covariance, liquidity và các nhân tố chung."},{"id":"S01-03","los_ids":["CFA26-09-03-LOS01"],"heading_vi":"Trade-off và chi phí","body_vi":"Mỗi khoản đầu tư cần xét marginal contribution to return và marginal contribution to portfolio risk, cùng phí giao dịch, thuế, khả năng thực hiện và vị trí trong benchmark. Nắm quá nhiều khoản tương tự có thể tăng chi phí mà giảm rủi ro rất ít."},{"id":"S01-04","los_ids":["CFA26-09-03-LOS01"],"heading_vi":"Diversification ratio","body_vi":"Một thước đo mô tả khả năng giảm total σ là DR=Σw_iσ_i/σp với weights không âm. DR>1 khi có diversification benefit; đây không phải performance ratio và không thay thế kiểm tra tail risk."},{"id":"S02-01","los_ids":["CFA26-09-03-LOS02"],"heading_vi":"Planning","body_vi":"Tìm hiểu objectives, willingness/ability to bear risk, liabilities, liquidity, tax, horizon, legal constraints và yêu cầu riêng. Lập Investment Policy Statement (IPS) có thể kiểm tra được, nêu benchmark và cơ chế review."},{"id":"S02-02","los_ids":["CFA26-09-03-LOS02"],"heading_vi":"Execution","body_vi":"Chuyển IPS thành strategic asset allocation, security selection, risk budgeting và trading có kiểm soát chi phí. Top-down bắt đầu từ kinh tế/nhóm tài sản; bottom-up chọn chứng khoán cụ thể; thực tế có thể phối hợp."},{"id":"S02-03","los_ids":["CFA26-09-03-LOS02"],"heading_vi":"Feedback","body_vi":"Theo dõi changes in client circumstances và market conditions, performance measurement, attribution, risk monitoring; rebalance khi trọng số lệch ngưỡng hoặc assumptions thay đổi. Không nên thay IPS chỉ vì thị trường biến động ngắn."},{"id":"S02-04","los_ids":["CFA26-09-03-LOS02"],"heading_vi":"Tính tuần hoàn và governance","body_vi":"Portfolio management process là chu trình Planning → Execution → Feedback → Planning. Mọi thay đổi quan trọng trong objectives/constraints cần phê duyệt, ghi nhận và cập nhật IPS, tạo bằng chứng kỷ luật đầu tư."},{"id":"S02-05","los_ids":["CFA26-09-03-LOS02"],"heading_vi":"Phân biệt performance appraisal","body_vi":"Measurement tính return; attribution giải thích nguồn return từ allocation/selection; evaluation đánh giá có đạt mục tiêu và đáng giá sau điều chỉnh risk/fees. Một lần outperform không chứng minh skill bền vững."},{"id":"S03-01","los_ids":["CFA26-09-03-LOS03"],"heading_vi":"Cá nhân và hộ gia đình","body_vi":"Individual investors có mục tiêu học phí, nghỉ hưu, mua nhà, bất động sản; cần lập bảng cash flows, mức chịu lỗ, thuế, vốn dự phòng và willingness. Human capital và khả năng tạo thu nhập trong tương lai ảnh hưởng capacity."},{"id":"S03-02","los_ids":["CFA26-09-03-LOS03"],"heading_vi":"Định chế hưu trí","body_vi":"Pension plans quản lý liabilities từ quyền lợi hưu trí; DB plan phải cân đối assets/liabilities, duration và funding; DC plan chuyển investment risk chủ yếu sang thành viên. Chính sách tài trợ của sponsor quan trọng với DB."},{"id":"S03-03","los_ids":["CFA26-09-03-LOS03"],"heading_vi":"Bảo hiểm và ngân hàng","body_vi":"Insurer có future policy claims và quy định vốn nên quan tâm matching duration, credit quality, liquidity; bank có liquidity obligations và regulatory capital. Không thể dùng allocation quỹ endowment cho một ngân hàng mà bỏ qua liability constraints."},{"id":"S03-04","los_ids":["CFA26-09-03-LOS03"],"heading_vi":"Endowments và foundations","body_vi":"Endowment trường học/viện có horizon dài và chi tiêu hàng năm, có thể nắm illiquid assets nếu đủ cash buffer. Foundation có grantmaking obligations và donor restrictions; mục tiêu duy trì sức mua và mức spending rate cần nhất quán."},{"id":"S03-05","los_ids":["CFA26-09-03-LOS03"],"heading_vi":"Sovereign wealth funds và các định chế khác","body_vi":"SWF có mục tiêu đa dạng như ổn định ngân sách, tiết kiệm cho thế hệ tương lai hoặc phát triển chiến lược; nhu cầu liquidity và tolerance khác nhau. Các đối tượng đều cần IPS riêng, không gán allocation duy nhất theo tên loại hình."},{"id":"S04-01","los_ids":["CFA26-09-03-LOS04"],"heading_vi":"Defined contribution: ai chịu rủi ro?","body_vi":"DC plan quy định contributions (ví dụ phần trăm lương) chứ không bảo đảm benefit cuối kỳ. Thành viên thường chịu investment outcome, longevity risk và mức thu nhập hưu trí chưa chắc chắn; sponsor chủ yếu có nghĩa vụ nộp contributions theo hợp đồng."},{"id":"S04-02","los_ids":["CFA26-09-03-LOS04"],"heading_vi":"Defined benefit: ai chịu rủi ro?","body_vi":"DB plan cam kết mức benefit theo formula thường dựa salary và service years. Sponsor/plan chịu investment và actuarial funding risk; cần tính PV obligations, funded status, mortality, discount rate, salary growth và liquidity payout."},{"id":"S04-03","los_ids":["CFA26-09-03-LOS04"],"heading_vi":"Liability-driven investment","body_vi":"DB plan có thể ghép fixed-income duration với pension obligations và quản lý funding-ratio volatility. DC participants nên chọn glide path, diversified asset mix và retirement income phù hợp tuổi, target date không mặc nhiên loại bỏ mọi rủi ro."},{"id":"S04-04","los_ids":["CFA26-09-03-LOS04"],"heading_vi":"Điểm dễ nhầm","body_vi":"DC có contributions biết trước và benefits không biết trước; DB có benefits quy định và contributions cần điều chỉnh. Mức return vượt kế hoạch đầu tư không tự động làm thành viên DC được đảm bảo benefit như DB."},{"id":"S04-05","los_ids":["CFA26-09-03-LOS04"],"heading_vi":"Lựa chọn theo hoàn cảnh","body_vi":"Cân nhắc khả năng chuyển việc, vesting, lifetime payments, inflation indexation và regulations từng quốc gia; không kết luận một loại chắc chắn tốt hơn cho mọi người."},{"id":"S05-01","los_ids":["CFA26-09-03-LOS05"],"heading_vi":"Buy side, sell side và fiduciary duties","body_vi":"Buy-side tổ chức đầu tư tiền của clients/funds (asset managers, pension funds); sell-side môi giới/ngân hàng đầu tư cung cấp research, market-making, capital-raising. Conflicts of interest và best execution cần được quản trị, bên mua không mặc định không có xung đột."},{"id":"S05-02","los_ids":["CFA26-09-03-LOS05"],"heading_vi":"Active và passive management","body_vi":"Active cố tạo alpha so benchmark bằng research/selection/timing và thường tốn phí cao; passive cố theo chỉ số, chịu tracking error và costs. Sau phí, outperformance bền vững khó duy trì và investor phải xem benchmark phù hợp."},{"id":"S05-03","los_ids":["CFA26-09-03-LOS05"],"heading_vi":"Business models và fees","body_vi":"Asset managers thường thu AUM-based fees, có thể thêm performance fees; fee basis, high-water marks và share classes thay đổi net returns. Scale có thể giảm unit cost nhưng không loại bỏ conflict khi khuyến khích tăng AUM bằng cách chấp nhận capacity constraints."},{"id":"S05-04","los_ids":["CFA26-09-03-LOS05"],"heading_vi":"Ngành thay đổi bởi công nghệ và quy định","body_vi":"Robo-advisers, quantitative investing, ETFs, ESG/AI analytics và compliance automation làm thay đổi phân phối sản phẩm, reporting và cost structures. Cần đánh giá tính minh bạch của thuật toán và trách nhiệm quản trị, không coi tự động hóa đồng nghĩa tư vấn phù hợp mọi khách hàng."},{"id":"S06-01","los_ids":["CFA26-09-03-LOS06"],"heading_vi":"Mutual funds và NAV","body_vi":"Open-end mutual fund phát hành/thu hồi units trực tiếp với fund theo NAV tại thời điểm định giá; investor nhận diversification và professional management nhưng chịu expense ratio, redemption terms và các khoản phí liên quan."},{"id":"S06-02","los_ids":["CFA26-09-03-LOS06"],"heading_vi":"ETFs và giá giao dịch","body_vi":"ETF shares thường mua bán intra-day trên secondary exchange với market price có thể premium/discount NAV. Authorized participants và creation/redemption mechanism thường thu hẹp chênh lệch, nhưng tracking error và market liquidity vẫn tồn tại."},{"id":"S06-03","los_ids":["CFA26-09-03-LOS06"],"heading_vi":"Closed-end funds","body_vi":"Closed-end fund có số shares niêm yết tương đối cố định, giao dịch trên secondary market; discount/premium to NAV có thể duy trì lâu do supply/demand và cấu trúc. Phải phân biệt fund NAV return với investor return từ market price."},{"id":"S06-04","los_ids":["CFA26-09-03-LOS06"],"heading_vi":"SMAs, hedge funds, private partnerships","body_vi":"Separately managed accounts không phải pooled fund vì mỗi khách hàng sở hữu portfolio riêng và có tùy biến constraints/thuế; hedge funds/private pools thường có restrictions, lockups, performance fees và investor eligibility."},{"id":"S06-05","los_ids":["CFA26-09-03-LOS06"],"heading_vi":"So sánh chi phí và định giá","body_vi":"Đọc redemption frequency, NAV valuation, liquidity, leverage, market price, tax efficiency, fee structure và investment mandate. Không đánh đồng ETF với passive: vẫn có active ETFs, trong khi mutual funds cũng có index funds."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-03-LOS01"],"expression":"E(Rp)=Σwi E(Ri)","variables":["Portfolio weights sum to 1."],"assumptions":["Same horizon and currency."]},{"id":"F01-02","los_ids":["CFA26-09-03-LOS01"],"expression":"Diversification ratio=Σwi σi / σp","variables":["Long-only weights and positive portfolio standard deviation."],"assumptions":["Descriptive measure, not a risk-free performance guarantee."]},{"id":"F02-01","los_ids":["CFA26-09-03-LOS02"],"expression":"Active weight_i = w_actual,i − w_benchmark,i","variables":["Weights from same date."],"assumptions":["Used in execution/performance attribution."]},{"id":"F02-02","los_ids":["CFA26-09-03-LOS02"],"expression":"Rebalancing trade_i = Target value_i − Current value_i","variables":["Requires updated total portfolio value and target weights."],"assumptions":["Ignoring transaction costs/taxes in simple illustration."]},{"id":"F03-01","los_ids":["CFA26-09-03-LOS03"],"expression":"Funding ratio=Plan assets / PV pension liabilities","variables":["Relevant for defined-benefit liability context."],"assumptions":["Asset/liability values measured on consistent date/basis."]},{"id":"F04-01","los_ids":["CFA26-09-03-LOS04"],"expression":"DB funded status = Fair value of plan assets − PV(DBO)","variables":["DBO defined benefit obligation."],"assumptions":["Accounting and regulatory funded-status definitions may vary."]},{"id":"F05-01","los_ids":["CFA26-09-03-LOS05"],"expression":"Net return ≈ Gross return − AUM fee","variables":["Approximation before taxes, other costs, compounding."],"assumptions":["Fee charged on comparable basis and period."]},{"id":"F05-02","los_ids":["CFA26-09-03-LOS05"],"expression":"Active return = Rp − Rbenchmark","variables":["Same period and net/gross fee basis."],"assumptions":["Return difference alone is not skill evidence."]},{"id":"F06-01","los_ids":["CFA26-09-03-LOS06"],"expression":"NAV per share=(Assets−Liabilities)/Fund shares","variables":["Assets/liabilities valued at relevant NAV time."],"assumptions":["Mutual funds transact at specified NAV dealing cycle."]},{"id":"F06-02","los_ids":["CFA26-09-03-LOS06"],"expression":"Premium to NAV=(Market price−NAV)/NAV","variables":["Applies to market-traded fund shares."],"assumptions":["Premium positive, discount negative."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-03-LOS01"],"problem":"Danh mục 50/50, σA=20%, σB=10%, ρ=0; tính DR.","solution_steps":["σp=√(0,5²×0,2²+0,5²×0,1²)=11,18%.","Weighted stand-alone σ=0,5×20%+0,5×10%=15%.","DR=15/11,18≈1,342; vượt 1 nhờ correlation không hoàn hảo."],"answer":"Diversification ratio ≈1,34."},{"id":"E01-02","los_ids":["CFA26-09-03-LOS01"],"problem":"Đang có 100% energy equity, dự kiến thêm utility equity có correlation 0,4.","solution_steps":["Xem expected return, pairwise covariance và tỷ trọng, không chỉ volatility utility.","Khả năng giảm concentration vào oil price là yếu tố hỗ trợ nhưng phải xét common market beta."],"answer":"Nên phân tích contribution to portfolio risk, không chọn asset riêng theo return cao nhất."},{"id":"E02-01","los_ids":["CFA26-09-03-LOS02"],"problem":"Danh mục 1 tỷ: equity target60%, bond40%; hiện equity650 triệu, bond350 triệu. Cần tái cân bằng?","solution_steps":["Equity target=600 triệu; bond target=400 triệu.","Nếu chưa có cashflow, bán equity50 triệu và mua bond50 triệu.","Cân nhắc transaction costs và tax trong triển khai thực tế."],"answer":"Tái cân bằng 50 triệu từ equity sang bond để quay về 60/40."},{"id":"E02-02","los_ids":["CFA26-09-03-LOS02"],"problem":"Khách hàng sắp nghỉ hưu, thời hạn cần rút tiền giảm từ 10 năm xuống 6 tháng.","solution_steps":["Đây là thay đổi trọng yếu về liability và horizon, quay về Planning/IPS.","Execution không tự động tiếp tục giữ allocation cũ nếu capacity suy giảm."],"answer":"Cập nhật IPS và xem lại liquidity allocation trước các giao dịch mới."},{"id":"E03-01","los_ids":["CFA26-09-03-LOS03"],"problem":"DB pension plan có assets 850 triệu và liabilities PV1.000 triệu. Funding ratio?","solution_steps":["Funding ratio=850/1.000=0,85.","Funding gap=150 triệu; sponsor có thể cần tăng contributions hoặc quản lý liabilities."],"answer":"Funding ratio 85%; plan đang underfunded."},{"id":"E03-02","los_ids":["CFA26-09-03-LOS03"],"problem":"Trường đại học có endowment 100 triệu, spending policy 4% tài sản đầu kỳ.","solution_steps":["Annual planned spending=4 triệu trong giả định không có điều chỉnh smoothing.","Portfolio cần dự phòng cash distributions và duy trì purchasing power dài hạn."],"answer":"Mức chi dự kiến 4 triệu, đồng thời duy trì khả năng đầu tư dài hạn."},{"id":"E04-01","los_ids":["CFA26-09-03-LOS04"],"problem":"DB assets 600, DBO 700, tính funded status.","solution_steps":["Funded status=600−700=−100 triệu.","Underfunded by 100; có thể cần tăng đóng góp hoặc điều chỉnh investment/risk strategy."],"answer":"DB funded status âm 100 triệu."},{"id":"E04-02","los_ids":["CFA26-09-03-LOS04"],"problem":"Người lao động được công ty đóng cố định 8% lương vào tài khoản riêng, thu nhập khi nghỉ phụ thuộc thị trường.","solution_steps":["Quyền lợi cuối kỳ phụ thuộc contribution + returns, không có benefit formula bảo đảm.","Đây là DC plan; người lao động chịu phần lớn investment risk."],"answer":"Phân loại DC, không phải DB pension."},{"id":"E05-01","los_ids":["CFA26-09-03-LOS05"],"problem":"Quỹ có gross return 9% và expense 1,2%/năm. Net return xấp xỉ?","solution_steps":["Net≈9−1,2=7,8%.","Nếu expense khác transaction costs, returns có thể thấp hơn nữa."],"answer":"Net approximately 7,8%/năm trước thuế, trong xấp xỉ đơn giản."},{"id":"E05-02","los_ids":["CFA26-09-03-LOS05"],"problem":"Passive equity ETF có annual tracking difference −0,3% so với index.","solution_steps":["Tracking difference có thể đến từ management fee, replication, taxes và cash drag.","Không đồng nghĩa manager cố tạo active alpha âm; benchmark matching quan trọng hơn outperform."],"answer":"Cần đánh giá tracking quality và chi phí, không coi ETF là risk-free."},{"id":"E06-01","los_ids":["CFA26-09-03-LOS06"],"problem":"ETF market price=101, NAV=100. Premium?","solution_steps":["Premium=(101−100)/100=1%.","Market price khác NAV có thể do demand/liquidity nhưng arbitrage của AP thường giới hạn lệch."],"answer":"ETF giao dịch premium 1% so NAV."},{"id":"E06-02","los_ids":["CFA26-09-03-LOS06"],"problem":"Fund assets=520 triệu, liabilities=20 triệu, units=50 triệu. NAV/unit?","solution_steps":["Net assets=520−20=500 triệu.","NAV per unit=500/50=10.","Giá giao dịch ETF hoặc closed-end fund có thể khác 10 nếu market price premium/discount."],"answer":"NAV mỗi đơn vị=10 đồng theo đơn vị tiền số liệu cho."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-03-LOS01"],"stem":"Portfolio approach nhấn mạnh điều gì?","options":["Tác động của mỗi khoản đầu tư lên toàn danh mục","Chỉ chọn cổ phiếu σ thấp nhất","Tối đa hóa return mỗi mã riêng"],"correct_option":0,"explanation":"Portfolio perspective xem covariance, weights và contribution to aggregate risk/return; nhìn từng mã biệt lập có thể dẫn đến phân bổ không tối ưu."},{"id":"Q01-02","los_ids":["CFA26-09-03-LOS01"],"stem":"Diversification ratio lớn hơn 1 chủ yếu cho biết?","options":["Danh mục có Jensen alpha dương","Có lợi ích giảm σ so với weighted stand-alone σ","Không còn tail risk"],"correct_option":1,"explanation":"DR>1 phản ánh diversification ở mức standard deviation, không trực tiếp đo alpha hoặc tail losses."},{"id":"Q01-03","los_ids":["CFA26-09-03-LOS01"],"stem":"Diversification luôn loại bỏ được rủi ro nào?","options":["Systematic market risk","Lạm phát toàn nền kinh tế","Một phần rủi ro riêng lẻ"],"correct_option":2,"explanation":"Nhiều khoản đầu tư ít tương quan giúp giảm idiosyncratic risk nhưng không loại bỏ cú sốc thị trường chung."},{"id":"Q02-01","los_ids":["CFA26-09-03-LOS02"],"stem":"Trình tự đúng của portfolio management process?","options":["Planning→Execution→Feedback","Feedback→Execution→Planning","Execution→Feedback→Planning"],"correct_option":0,"explanation":"Bắt đầu từ objectives/IPS rồi triển khai, sau đó đo lường và phản hồi để điều chỉnh theo điều kiện mới."},{"id":"Q02-02","los_ids":["CFA26-09-03-LOS02"],"stem":"Performance attribution giúp trả lời?","options":["Chỉ tính risk-free rate","Nguồn đóng góp vào active return từ allocation/selection","Chỉ xác định số tiền tiết kiệm thuế"],"correct_option":1,"explanation":"Attribution phân tích quyết định tạo active return, khác measurement chỉ tính return tổng."},{"id":"Q02-03","los_ids":["CFA26-09-03-LOS02"],"stem":"Khách hàng đổi thời hạn rút tiền từ 10 năm sang 3 tháng, nên làm gì trước?","options":["Mua cổ phiếu tăng trưởng","Giữ IPS cũ bất kể hoàn cảnh","Rà soát lại IPS và liquidity need"],"correct_option":2,"explanation":"Liability sắp phát sinh thay đổi constraints; bắt đầu từ bước planning rồi mới điều chỉnh execution."},{"id":"Q03-01","los_ids":["CFA26-09-03-LOS03"],"stem":"Định chế nào quan tâm matching liability duration đặc biệt?","options":["Life insurance company","Equity-only day trader","Start-up VC fund"],"correct_option":0,"explanation":"Life insurer có quyền lợi bảo hiểm tương lai, cần quan tâm duration/liquidity/credit để chi trả nghĩa vụ."},{"id":"Q03-02","los_ids":["CFA26-09-03-LOS03"],"stem":"Endowment thường cần?","options":["Đòn bẩy tối đa","Chi tiêu đều và duy trì sức mua dài hạn","Đóng tài khoản sau 1 ngày"],"correct_option":1,"explanation":"Endowment thường có horizon dài nhưng phải phân phối theo spending policy, nên cân bằng liquidity và real return."},{"id":"Q03-03","los_ids":["CFA26-09-03-LOS03"],"stem":"DB pension có asset PV850, liability PV1.000; funding ratio?","options":["115%","1.000%","85%"],"correct_option":2,"explanation":"Funding ratio = plan assets/liability PV = 850/1000=0,85; không nhầm funding gap với tỷ lệ."},{"id":"Q04-01","los_ids":["CFA26-09-03-LOS04"],"stem":"Trong DC plan, yếu tố thường xác định từ đầu là?","options":["Contribution rule","Retirement benefit guaranteed","Investment return 10% chắc chắn"],"correct_option":0,"explanation":"DC quy định đóng góp, còn giá trị tích lũy và benefits tùy kết quả đầu tư; không có guaranteed return chung."},{"id":"Q04-02","los_ids":["CFA26-09-03-LOS04"],"stem":"DB plan thường chuyển investment risk chủ yếu tới?","options":["Mỗi thành viên tự quản lý","Sponsor/plan","Ngân hàng trung ương"],"correct_option":1,"explanation":"DB có benefit formula nên sponsor/plan phải quản lý tài sản và trách nhiệm chi trả nếu funded gap phát sinh."},{"id":"Q04-03","los_ids":["CFA26-09-03-LOS04"],"stem":"DB assets 600, PV obligations700; funded status?","options":["+100","0","−100"],"correct_option":2,"explanation":"Fair value assets trừ DBO = 600−700=−100, cho biết thiếu nguồn lực so với obligations."},{"id":"Q05-01","los_ids":["CFA26-09-03-LOS05"],"stem":"Active manager thường tìm cách?","options":["Tạo alpha sau phí bằng active decisions","Luôn nắm treasury bills","Bám chỉ số với tracking error 0 bắt buộc"],"correct_option":0,"explanation":"Active decisions chọn chứng khoán, phân bổ hoặc timing để vượt benchmark; kết quả không được bảo đảm."},{"id":"Q05-02","los_ids":["CFA26-09-03-LOS05"],"stem":"Sell-side thường tham gia hoạt động nào?","options":["Chỉ trả benefit hưu trí","Brokerage, research, underwriting","Quản lý portfolio của endowment là chức năng duy nhất"],"correct_option":1,"explanation":"Sell-side cung cấp dịch vụ phát hành, nghiên cứu và giao dịch cho market participants; buy-side đầu tư/quản lý tiền."},{"id":"Q05-03","los_ids":["CFA26-09-03-LOS05"],"stem":"Gross return9%, management fee1,2%; net gần nhất?","options":["9,0%","10,2%","7,8%"],"correct_option":2,"explanation":"Return sau phí xấp xỉ gross−fee=7,8%; phải xét các phí khác nếu đề cung cấp."},{"id":"Q06-01","los_ids":["CFA26-09-03-LOS06"],"stem":"ETF khác open-end mutual fund điển hình ở điểm nào?","options":["Có thể giao dịch intraday trên sàn","Không có NAV","Không được đa dạng hóa"],"correct_option":0,"explanation":"ETF giao dịch theo market price intraday; open-end mutual funds thường tạo/thu hồi units theo NAV cuối kỳ dealing."},{"id":"Q06-02","los_ids":["CFA26-09-03-LOS06"],"stem":"Market price 101, NAV100; premium?","options":["+10%","+1%","−1%"],"correct_option":1,"explanation":"(101−100)/100=+1%; stock exchange price có thể cao hơn NAV. Đáp án −1% đổi sai dấu vì market price lớn hơn NAV; +10% nhầm tỷ lệ phần trăm."},{"id":"Q06-03","los_ids":["CFA26-09-03-LOS06"],"stem":"SMA khác pooled investment vì?","options":["Luôn phải passive","Bắt buộc có liquidity thấp","Portfolio được quản lý riêng theo từng khách hàng"],"correct_option":2,"explanation":"Separately managed account là tài khoản riêng, có thể tùy chỉnh mandate và constraints, khác pooled ownership."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-03-LOS01"],"front":"Đánh giá đóng góp vào toàn danh mục — giải thích và ứng dụng?","back":"Portfolio approach không đánh giá từng khoản đầu tư riêng rẽ mà xem mức độ thay đổi expected return, total risk và concentration của toàn bộ tài sản sau khi thêm vị thế. Một cổ phiếu nhiều biến động vẫn có thể giảm tổng volatility nếu tương quan đủ thấp với holdings còn lại."},{"id":"C01-02","los_ids":["CFA26-09-03-LOS01"],"front":"Lợi ích của diversification — giải thích và ứng dụng?","back":"Kết hợp nguồn sinh lợi khác nhau giảm idiosyncratic risk và hạn chế tổn thất lớn tập trung ở một doanh nghiệp. Diversification không triệt tiêu systematic risk hoặc bảo đảm lãi trong khủng hoảng; cần xem covariance, liquidity và các nhân tố chung."},{"id":"C01-03","los_ids":["CFA26-09-03-LOS01"],"front":"Trade-off và chi phí — giải thích và ứng dụng?","back":"Mỗi khoản đầu tư cần xét marginal contribution to return và marginal contribution to portfolio risk, cùng phí giao dịch, thuế, khả năng thực hiện và vị trí trong benchmark. Nắm quá nhiều khoản tương tự có thể tăng chi phí mà giảm rủi ro rất ít."},{"id":"C02-01","los_ids":["CFA26-09-03-LOS02"],"front":"Planning — giải thích và ứng dụng?","back":"Tìm hiểu objectives, willingness/ability to bear risk, liabilities, liquidity, tax, horizon, legal constraints và yêu cầu riêng. Lập Investment Policy Statement (IPS) có thể kiểm tra được, nêu benchmark và cơ chế review."},{"id":"C02-02","los_ids":["CFA26-09-03-LOS02"],"front":"Execution — giải thích và ứng dụng?","back":"Chuyển IPS thành strategic asset allocation, security selection, risk budgeting và trading có kiểm soát chi phí. Top-down bắt đầu từ kinh tế/nhóm tài sản; bottom-up chọn chứng khoán cụ thể; thực tế có thể phối hợp."},{"id":"C02-03","los_ids":["CFA26-09-03-LOS02"],"front":"Feedback — giải thích và ứng dụng?","back":"Theo dõi changes in client circumstances và market conditions, performance measurement, attribution, risk monitoring; rebalance khi trọng số lệch ngưỡng hoặc assumptions thay đổi. Không nên thay IPS chỉ vì thị trường biến động ngắn."},{"id":"C03-01","los_ids":["CFA26-09-03-LOS03"],"front":"Cá nhân và hộ gia đình — giải thích và ứng dụng?","back":"Individual investors có mục tiêu học phí, nghỉ hưu, mua nhà, bất động sản; cần lập bảng cash flows, mức chịu lỗ, thuế, vốn dự phòng và willingness. Human capital và khả năng tạo thu nhập trong tương lai ảnh hưởng capacity."},{"id":"C03-02","los_ids":["CFA26-09-03-LOS03"],"front":"Định chế hưu trí — giải thích và ứng dụng?","back":"Pension plans quản lý liabilities từ quyền lợi hưu trí; DB plan phải cân đối assets/liabilities, duration và funding; DC plan chuyển investment risk chủ yếu sang thành viên. Chính sách tài trợ của sponsor quan trọng với DB."},{"id":"C03-03","los_ids":["CFA26-09-03-LOS03"],"front":"Bảo hiểm và ngân hàng — giải thích và ứng dụng?","back":"Insurer có future policy claims và quy định vốn nên quan tâm matching duration, credit quality, liquidity; bank có liquidity obligations và regulatory capital. Không thể dùng allocation quỹ endowment cho một ngân hàng mà bỏ qua liability constraints."},{"id":"C04-01","los_ids":["CFA26-09-03-LOS04"],"front":"Defined contribution: ai chịu rủi ro? — giải thích và ứng dụng?","back":"DC plan quy định contributions (ví dụ phần trăm lương) chứ không bảo đảm benefit cuối kỳ. Thành viên thường chịu investment outcome, longevity risk và mức thu nhập hưu trí chưa chắc chắn; sponsor chủ yếu có nghĩa vụ nộp contributions theo hợp đồng."},{"id":"C04-02","los_ids":["CFA26-09-03-LOS04"],"front":"Defined benefit: ai chịu rủi ro? — giải thích và ứng dụng?","back":"DB plan cam kết mức benefit theo formula thường dựa salary và service years. Sponsor/plan chịu investment và actuarial funding risk; cần tính PV obligations, funded status, mortality, discount rate, salary growth và liquidity payout."},{"id":"C04-03","los_ids":["CFA26-09-03-LOS04"],"front":"Liability-driven investment — giải thích và ứng dụng?","back":"DB plan có thể ghép fixed-income duration với pension obligations và quản lý funding-ratio volatility. DC participants nên chọn glide path, diversified asset mix và retirement income phù hợp tuổi, target date không mặc nhiên loại bỏ mọi rủi ro."},{"id":"C05-01","los_ids":["CFA26-09-03-LOS05"],"front":"Buy side, sell side và fiduciary duties — giải thích và ứng dụng?","back":"Buy-side tổ chức đầu tư tiền của clients/funds (asset managers, pension funds); sell-side môi giới/ngân hàng đầu tư cung cấp research, market-making, capital-raising. Conflicts of interest và best execution cần được quản trị, bên mua không mặc định không có xung đột."},{"id":"C05-02","los_ids":["CFA26-09-03-LOS05"],"front":"Active và passive management — giải thích và ứng dụng?","back":"Active cố tạo alpha so benchmark bằng research/selection/timing và thường tốn phí cao; passive cố theo chỉ số, chịu tracking error và costs. Sau phí, outperformance bền vững khó duy trì và investor phải xem benchmark phù hợp."},{"id":"C05-03","los_ids":["CFA26-09-03-LOS05"],"front":"Business models và fees — giải thích và ứng dụng?","back":"Asset managers thường thu AUM-based fees, có thể thêm performance fees; fee basis, high-water marks và share classes thay đổi net returns. Scale có thể giảm unit cost nhưng không loại bỏ conflict khi khuyến khích tăng AUM bằng cách chấp nhận capacity constraints."},{"id":"C06-01","los_ids":["CFA26-09-03-LOS06"],"front":"Mutual funds và NAV — giải thích và ứng dụng?","back":"Open-end mutual fund phát hành/thu hồi units trực tiếp với fund theo NAV tại thời điểm định giá; investor nhận diversification và professional management nhưng chịu expense ratio, redemption terms và các khoản phí liên quan."},{"id":"C06-02","los_ids":["CFA26-09-03-LOS06"],"front":"ETFs và giá giao dịch — giải thích và ứng dụng?","back":"ETF shares thường mua bán intra-day trên secondary exchange với market price có thể premium/discount NAV. Authorized participants và creation/redemption mechanism thường thu hẹp chênh lệch, nhưng tracking error và market liquidity vẫn tồn tại."},{"id":"C06-03","los_ids":["CFA26-09-03-LOS06"],"front":"Closed-end funds — giải thích và ứng dụng?","back":"Closed-end fund có số shares niêm yết tương đối cố định, giao dịch trên secondary market; discount/premium to NAV có thể duy trì lâu do supply/demand và cấu trúc. Phải phân biệt fund NAV return với investor return từ market price."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_PDFs"},{"module_id":"CFA26-09-04","title":"Basics of Portfolio Planning and Construction","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[169,212],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[118,129],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[135,173],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-04-LOS01","learning_goal_vi":"Mô tả vì sao cần bản Investment Policy Statement (IPS) bằng văn bản.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":171},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":118},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":135}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS02","learning_goal_vi":"Mô tả các thành phần chủ yếu của IPS.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S02-01","S02-02","S02-03","S02-04"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":172},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":118},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":137}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS03","learning_goal_vi":"Mô tả cách xác định mục tiêu lợi suất và rủi ro phù hợp cho khách hàng.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S03-01","S03-02","S03-03","S03-04"],"formula_ids":["F03-01","F03-02"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":174},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":119},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":139}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS04","learning_goal_vi":"Giải thích khác biệt willingness với ability (capacity) to take risk.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S04-01","S04-02","S04-03","S04-04"],"formula_ids":["F04-01"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":176},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":119},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":141}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS05","learning_goal_vi":"Mô tả tác động của liquidity, time horizon, tax, legal và unique constraints.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S05-01","S05-02","S05-03","S05-04","S05-05","S05-06"],"formula_ids":["F05-01"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":181},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":120},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":143}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS06","learning_goal_vi":"Giải thích lựa chọn và định nghĩa asset classes phục vụ asset allocation.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S06-01","S06-02","S06-03","S06-04","S06-05"],"formula_ids":["F06-01"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":189},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":121},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":150}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS07","learning_goal_vi":"Mô tả nguyên tắc xây dựng danh mục và vai trò asset allocation so với IPS.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S07-01","S07-02","S07-03","S07-04","S07-05","S07-06"],"formula_ids":["F07-01","F07-02"],"example_ids":["E07-01","E07-02"],"question_ids":["Q07-01","Q07-02","Q07-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":192},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":123},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":153}},"missing_items":[]},{"los_id":"CFA26-09-04-LOS08","learning_goal_vi":"Mô tả các cách tích hợp ESG trong lập kế hoạch và xây dựng danh mục.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Đối chiếu phạm vi LOS Curriculum 2026 và sources liên quan","Giải thích chuyên sâu bằng tiếng Việt, có ngoại lệ","Ví dụ áp dụng và câu hỏi tự biên soạn theo LOS","Kiểm tra cấu trúc, phép tính mẫu và khả năng hiển thị"],"concept_ids":["S08-01","S08-02","S08-03","S08-04","S08-05"],"formula_ids":["F08-01"],"example_ids":["E08-01","E08-02"],"question_ids":["Q08-01","Q08-02","Q08-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":203},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":124},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":145}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-04-LOS01"],"heading_vi":"IPS là thỏa thuận có hệ thống","body_vi":"Investment Policy Statement ghi rõ objectives, constraints, risk tolerance, benchmark và quy trình review để cả client lẫn manager có chuẩn ra quyết định. Văn bản làm rõ phạm vi discretion, trách nhiệm của các bên và tránh thay đổi theo tâm lý ngắn hạn."},{"id":"S01-02","los_ids":["CFA26-09-04-LOS01"],"heading_vi":"Kỷ luật khi thị trường biến động","body_vi":"Khi giá tài sản giảm sâu, IPS giúp đánh giá xem tổn thất có nằm trong phạm vi risk budget dự kiến và có thay đổi liability/ability không. IPS không cấm thay đổi danh mục, nhưng yêu cầu thay đổi theo quy trình và thông tin khách hàng chứ không phản ứng vội."},{"id":"S01-03","los_ids":["CFA26-09-04-LOS01"],"heading_vi":"Đánh giá hiệu quả và accountability","body_vi":"Benchmark và performance/risk measures được xác định trước tạo tiêu chuẩn đo lường rõ ràng. Không nên chọn benchmark sau khi biết return hoặc dùng ước tính risk tolerance cũ khi hoàn cảnh đã thay đổi."},{"id":"S01-04","los_ids":["CFA26-09-04-LOS01"],"heading_vi":"Quy trình cập nhật","body_vi":"IPS phải được kiểm tra định kỳ và bất cứ khi nào objectives, legal constraints, tax status, wealth hoặc liquidity thay đổi đáng kể; bản được phê duyệt cần có ngày hiệu lực và giao tiếp minh bạch với client."},{"id":"S02-01","los_ids":["CFA26-09-04-LOS02"],"heading_vi":"Return và risk objectives","body_vi":"IPS nêu required/desired return (nominal/real, trước/sau thuế/phí), risk limits theo volatility/drawdown/tracking error và capacity. Mục tiêu return phải khả thi với ràng buộc và phương án allocation."},{"id":"S02-02","los_ids":["CFA26-09-04-LOS02"],"heading_vi":"Investment constraints","body_vi":"Liệt kê liquidity needs, investment horizon, tax considerations, legal/regulatory limits và unique circumstances (L-T-L-L-U). Có thể bổ sung leverage limits, prohibited securities, currency exposure và concentration constraints."},{"id":"S02-03","los_ids":["CFA26-09-04-LOS02"],"heading_vi":"Strategic asset allocation và benchmark","body_vi":"IPS thường quy định target/ranges cho asset classes, benchmark phù hợp, rebalancing thresholds, sử dụng derivatives/illiquid assets và phương pháp risk monitoring. Không nhất thiết nêu từng mã cổ phiếu."},{"id":"S02-04","los_ids":["CFA26-09-04-LOS02"],"heading_vi":"Quản trị, reporting và review","body_vi":"Xác định roles, delegated authority, duties, review frequency, cách báo cáo performance và điều kiện thay đổi. Một IPS tốt đủ cụ thể để thực thi và đủ linh hoạt khi có event trọng yếu."},{"id":"S03-01","los_ids":["CFA26-09-04-LOS03"],"heading_vi":"Required và desired return","body_vi":"Required return xuất phát cashflow, liabilities, taxes, inflation, capital preservation; desired return là mức client mong muốn. Nếu desired return vượt mức khả thi với risk tolerance, cần điều chỉnh mục tiêu, đóng góp hoặc thời gian chứ không mặc định tăng leverage."},{"id":"S03-02","los_ids":["CFA26-09-04-LOS03"],"heading_vi":"Absolute và relative objectives","body_vi":"Absolute return target có thể biểu diễn nominal/real return hoặc bảo toàn vốn; relative return target so benchmark, inflation hay liability growth. Thời gian đo lường, gross/net fees và tax basis phải thống nhất."},{"id":"S03-03","los_ids":["CFA26-09-04-LOS03"],"heading_vi":"Risk objectives theo tài chính và tâm lý","body_vi":"Capacity dựa financial ability, liabilities, horizon; willingness dựa psychometric attitudes/experience. Có thể dùng volatility, downside deviation, expected shortfall, tracking error hoặc funded-ratio risk; mỗi thước đo chỉ phản ánh một lát cắt."},{"id":"S03-04","los_ids":["CFA26-09-04-LOS03"],"heading_vi":"Đánh giá tính khả thi","body_vi":"Dự báo strategic asset returns, correlations và khả năng drawdown; kiểm tra mục tiêu required return có tương thích rủi ro chấp nhận được. Stress tests cho trường hợp thị trường giảm và rút tiền sớm trước khi xác nhận IPS."},{"id":"S04-01","los_ids":["CFA26-09-04-LOS04"],"heading_vi":"Ability là năng lực tài chính khách quan","body_vi":"Xem net worth, employment income, liquidity needs, debt maturity, retirement horizon, liabilities và khả năng bù lỗ từ nguồn khác. Khách hàng nhiều tài sản nhưng tất cả bị ràng buộc cho nghĩa vụ ngắn hạn có capacity thấp hơn vẻ ngoài."},{"id":"S04-02","los_ids":["CFA26-09-04-LOS04"],"heading_vi":"Willingness là thái độ tâm lý","body_vi":"Khai thác kinh nghiệm đầu tư, phản ứng với drawdown, trade-offs giữa return và loss bằng phỏng vấn/scenarios. Mức willingness có thể thay đổi theo market cycle và chịu framing bias; không dùng một câu hỏi cảm tính làm kết luận cuối."},{"id":"S04-03","los_ids":["CFA26-09-04-LOS04"],"heading_vi":"Nguyên tắc mức chịu rủi ro thấp hơn","body_vi":"Nếu willingness rất cao nhưng ability thấp, portfolio phải giới hạn bởi ability để không đe dọa nghĩa vụ. Nếu ability cao nhưng willingness thấp, cố ép allocation mạo hiểm có thể khiến panic selling đúng đáy."},{"id":"S04-04","los_ids":["CFA26-09-04-LOS04"],"heading_vi":"Tác động vào IPS","body_vi":"Ghi risk tolerance kết hợp, mô tả risk budget và asset allocation constraints. Giải thích rõ tại sao tolerance thực tế có thể thấp hơn sở thích risk-seeking của khách hàng."},{"id":"S05-01","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Liquidity constraints","body_vi":"Cash withdrawals, spending needs, emergency buffer và margin calls quyết định phần tài sản cần dễ bán. Quỹ có liabilities thanh toán hàng tháng không nên đặt toàn bộ vào assets khóa rút 5 năm dù expected return hấp dẫn."},{"id":"S05-02","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Time horizon","body_vi":"Horizons có thể nhiều giai đoạn: accumulation, retirement withdrawals, estate transfer. Kỳ dài hỗ trợ chịu volatility tạm thời nhưng không xóa tail risk; short horizon thường tăng ưu tiên capital preservation và liquidity."},{"id":"S05-03","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Tax constraints","body_vi":"Xét marginal tax rates, capital gains treatment, tax-deferred accounts, loss harvesting và giao dịch phát sinh thuế. Tax-efficient allocation khác nhau tùy jurisdiction, nên không tự suy thuế suất nếu đề không cung cấp."},{"id":"S05-04","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Legal và regulatory limits","body_vi":"Tổ chức có statutory investment limits, fiduciary duty, leverage restrictions; cá nhân có trusts, lock-in, suitability rules. Phải ghi rõ jurisdiction và legal form trước khi quyết định allowed asset classes."},{"id":"S05-05","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Unique circumstances","body_vi":"ESG restrictions, concentrated employer stock, ownership of family business, currency of liabilities, charitable objectives và donor restrictions có thể giới hạn choices dù asset có return tốt."},{"id":"S05-06","los_ids":["CFA26-09-04-LOS05"],"heading_vi":"Risk of combined constraints","body_vi":"Constraints tương tác: time horizon 20 năm không cho phép bỏ qua cash need 2 tháng; tax-efficient strategy không được vi phạm luật hoặc unique requirement quan trọng khác."},{"id":"S06-01","los_ids":["CFA26-09-04-LOS06"],"heading_vi":"Asset class phải tương đồng bên trong","body_vi":"Một asset class nên có risk/return drivers tương đối giống nhau, khác biệt với nhóm khác, đủ lớn và có thể đo/đầu tư/định giá. Phân nhóm theo geography, duration, credit, public/private hoặc economic exposures tùy mandate."},{"id":"S06-02","los_ids":["CFA26-09-04-LOS06"],"heading_vi":"Tránh double-counting","body_vi":"Một quỹ multi-asset không thể vừa tính toàn bộ ở equity vừa toàn bộ ở bond; phải look-through underlying allocations nếu dữ liệu cho phép. Commodity futures khác physical commodities về cash collateral và roll yield."},{"id":"S06-03","los_ids":["CFA26-09-04-LOS06"],"heading_vi":"Investability và data","body_vi":"Asset class cần benchmark tin cậy, liquidity phù hợp, estimates of E(R), volatility, correlation, costs và tax treatments. Tài sản không giao dịch thường xuyên có unsmoothing problem và estimation risk."},{"id":"S06-04","los_ids":["CFA26-09-04-LOS06"],"heading_vi":"Chi tiết đủ để thể hiện risk","body_vi":"Nhóm fixed income có thể chia sovereign, IG corporate, high yield, duration và currency; nhóm equity theo region/sector/size; không dùng một nhóm quá rộng che lấp rủi ro cùng nhân tố."},{"id":"S06-05","los_ids":["CFA26-09-04-LOS06"],"heading_vi":"Asset class vs investment vehicle","body_vi":"ETF, mutual fund, SMA là cấu trúc đầu tư chứ không tự động là asset class. Ví dụ US equity ETF và index mutual fund cùng exposure equity Mỹ, không phải hai nhóm rủi ro độc lập."},{"id":"S07-01","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Strategic asset allocation là quyết định dài hạn","body_vi":"SAA chuyển goals/constraints thành target weights asset classes phù hợp liquidity, horizon, risk tolerance và required return. Nhiều nghiên cứu cho thấy allocation quan trọng trong quyết định mức rủi ro danh mục, nhưng không bảo đảm outperform benchmark."},{"id":"S07-02","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Tactical và dynamic allocation","body_vi":"Tactical asset allocation điều chỉnh ngắn hạn quanh SAA dựa valuation/business cycle; dynamic thường điều chỉnh theo market/liability/risk conditions. Các deviations cần risk budgets và giới hạn rõ trong IPS."},{"id":"S07-03","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Diversification và constraints","body_vi":"Portfolio construction phối hợp expected returns, variances, covariances, turnover, transaction costs, taxes và constraints. Optimization với estimation error có thể tạo corner weights cực đoan; robust methods, rebalancing bands và diversification caps giúp thực thi."},{"id":"S07-04","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Active/passive implementation","body_vi":"Một asset class target có thể được thực hiện bằng index ETF hoặc active mandate; decision selection liên quan tracking error, fees, manager skill và liquidity. Đánh giá post-fee và rủi ro concentration."},{"id":"S07-05","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Rebalancing theo định kỳ hoặc ngưỡng","body_vi":"Khi price movement khiến weight lệch target, rebalance đưa weights về vùng IPS và giúp duy trì exposure. Không nhất thiết rebalance mỗi ngày; chi phí và thuế có thể vượt lợi ích."},{"id":"S07-06","los_ids":["CFA26-09-04-LOS07"],"heading_vi":"Liên kết IPS","body_vi":"Portfolio optimum trên bảng tính không phù hợp nếu vi phạm legally prohibited securities, liquidity floor hoặc desired downside loss. Feasibility của IPS đứng trước bài toán tối ưu mean-variance."},{"id":"S08-01","los_ids":["CFA26-09-04-LOS08"],"heading_vi":"ESG as risk/return input","body_vi":"Environmental, social, governance factors có thể ảnh hưởng cash flows, cost of capital, litigation/transition risk và long-run competitive advantage. Cần xét materiality theo issuer/industry, tránh coi một ESG score duy nhất là toàn bộ phân tích."},{"id":"S08-02","los_ids":["CFA26-09-04-LOS08"],"heading_vi":"Negative/exclusionary screening","body_vi":"Loại sectors/securities không phù hợp values/mandate (ví dụ tobacco) theo lựa chọn client; thay đổi investable universe có thể tăng concentration/tracking error. Không tự coi exclusion tạo alpha dương hay giảm mọi rủi ro."},{"id":"S08-03","los_ids":["CFA26-09-04-LOS08"],"heading_vi":"Positive/best-in-class, integration và engagement","body_vi":"Best-in-class chọn issuers ESG tốt trong nhóm so sánh; ESG integration đưa dữ liệu material vào valuation/portfolio risk; engagement dùng quyền sở hữu để đối thoại/biểu quyết thay đổi governance."},{"id":"S08-04","los_ids":["CFA26-09-04-LOS08"],"heading_vi":"Thematic, impact và constraints","body_vi":"Thematic allocation tập trung chủ đề như renewable energy, có thể tăng concentration. Impact investing hướng tới measurable positive impact cùng financial return, cần thước đo kết quả và tránh greenwashing."},{"id":"S08-05","los_ids":["CFA26-09-04-LOS08"],"heading_vi":"IPS và đo lường","body_vi":"IPS nên ghi ESG objectives, prohibited sectors, proxy voting, reporting metrics, data limitations và cách xử lý trade-offs với risk/return/liquidity. ESG ratings khác nhà cung cấp có thể không đồng nhất; không được dùng thông tin marketing thay cho due diligence."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-04-LOS01"],"expression":"Active return = Portfolio return − IPS benchmark return","variables":["Use same performance horizon and fee treatment."],"assumptions":["Benchmark chosen ex ante in IPS."]},{"id":"F02-01","los_ids":["CFA26-09-04-LOS02"],"expression":"Real return objective=(1+nominal target)/(1+expected inflation)−1","variables":["Returns on consistent basis."],"assumptions":["Define before/after taxes and fees in IPS."]},{"id":"F03-01","los_ids":["CFA26-09-04-LOS03"],"expression":"Required real return=(1+nominal)/(1+inflation)−1","variables":["Same compounding period."],"assumptions":["Objective before/after tax must be defined."]},{"id":"F03-02","los_ids":["CFA26-09-04-LOS03"],"expression":"Target portfolio return = Σ w_i E(R_i)","variables":["Forward-looking estimates, not guarantee."],"assumptions":["Portfolio weights and expected asset class returns specified."]},{"id":"F04-01","los_ids":["CFA26-09-04-LOS04"],"expression":"Risk budget constraint: estimated downside loss ≤ capacity-based loss limit","variables":["Illustrative inequality, depends on chosen risk metric."],"assumptions":["Not a literal CFA guarantee of loss probability."]},{"id":"F05-01","los_ids":["CFA26-09-04-LOS05"],"expression":"Net liquidity needed = Expected cash outflows − Reliable near-term cash inflows","variables":["Relevant period and currency."],"assumptions":["Needs stress buffer; inflows may fail under stress."]},{"id":"F06-01","los_ids":["CFA26-09-04-LOS06"],"expression":"Asset exposure_i=Σ_vehicle w_vehicle × share_exposed_to_i","variables":["Underlying exposure shares sum appropriately."],"assumptions":["Look-through only when underlying data is available and reliable."]},{"id":"F07-01","los_ids":["CFA26-09-04-LOS07"],"expression":"Target allocation: Σ w_i=1","variables":["Bounds for each asset class may also apply."],"assumptions":["Fully invested target weights unless leverage/cash borrowing specified."]},{"id":"F07-02","los_ids":["CFA26-09-04-LOS07"],"expression":"Target value_i=Portfolio MV × target weight_i","variables":["MV measured on a consistent valuation date."],"assumptions":["Ignoring fees and taxes in simple rebalancing example."]},{"id":"F08-01","los_ids":["CFA26-09-04-LOS08"],"expression":"Tracking difference=Portfolio return−ESG benchmark return","variables":["Benchmark selected ex ante and appropriate."],"assumptions":["Not a direct measure of positive social impact."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-04-LOS01"],"problem":"Khách hàng yêu cầu bán hết cổ phiếu sau khi chỉ số giảm 15%, trong khi IPS có risk budget 20% và liabilities không đổi.","solution_steps":["Manager giải thích biến động so risk tolerance đã thống nhất.","Có thể cân nhắc rebalance và kiểm tra capacity; không tùy tiện thay objective chỉ dựa vào market noise."],"answer":"Dùng IPS làm cơ sở trao đổi và quyết định theo quy trình."},{"id":"E01-02","los_ids":["CFA26-09-04-LOS01"],"problem":"Quỹ có return 8%, IPS benchmark return=10%. Active return?","solution_steps":["Active return=8%−10%=−2 điểm %.","Không đổi benchmark thành money market chỉ để thể hiện outperform."],"answer":"Underperform IPS benchmark 2 điểm phần trăm."},{"id":"E02-01","los_ids":["CFA26-09-04-LOS02"],"problem":"IPS mục tiêu real return 3%, expected inflation 2%. Nominal target?","solution_steps":["(1+0,03)(1+0,02)−1=5,06%.","Mức 5% là xấp xỉ, còn 5,06% là đúng theo compounding."],"answer":"Nominal target 5,06% trước điều chỉnh phí/thuế nếu đề không nêu thêm."},{"id":"E02-02","los_ids":["CFA26-09-04-LOS02"],"problem":"Client cần 1 tỷ tiền mặt sau 6 tháng, hiện portfolio equity-heavy.","solution_steps":["Ghi liquidity need và horizon cụ thể trong IPS.","Phân bổ cash/short-duration assets hỗ trợ chi trả, dù return kỳ vọng thấp hơn equity."],"answer":"IPS phải ghi cả return objective lẫn liquidity constraint để allocation khả thi."},{"id":"E03-01","los_ids":["CFA26-09-04-LOS03"],"problem":"Client cần 500 triệu sau 5 năm, hiện có 400 triệu, không thêm tiền. CAGR required?","solution_steps":["Cần 400(1+r)^5=500.","r=(500/400)^(1/5)−1≈4,56%/năm trước thuế/phí.","Nếu fees hoặc inflation cần tính thêm để quy đổi target nominal/real."],"answer":"Required nominal CAGR khoảng 4,56% nếu chưa tính phí và thuế."},{"id":"E03-02","los_ids":["CFA26-09-04-LOS03"],"problem":"Portfolio 50% bond E=4%, 50% equity E=8%; expected return?","solution_steps":["E(Rp)=0,5×4%+0,5×8%=6%.","Phải xét volatility/covariance và client risk capacity trước khi gọi phân bổ này phù hợp."],"answer":"Expected portfolio return 6% theo giả định return của hai nhóm tài sản."},{"id":"E04-01","los_ids":["CFA26-09-04-LOS04"],"problem":"Client có 2 tỷ nhưng cần trả 1,8 tỷ sau 3 tháng, rất thích đầu cơ.","solution_steps":["Khả năng chịu lỗ cho phần nghĩa vụ rất hạn chế: money needed 1,8 tỷ cần ưu tiên thanh khoản.","Willingness cao không làm capacity tự tăng; nên tách buffer và risk budget phù hợp."],"answer":"Risk tolerance thực tế bị giới hạn bởi financial capacity."},{"id":"E04-02","los_ids":["CFA26-09-04-LOS04"],"problem":"Client triệu phú có horizon20 năm và không nợ nhưng thường hoảng sợ khi portfolio giảm 5%.","solution_steps":["Ability có thể cao, willingness thấp.","Tăng equity nhanh có thể dẫn tới selling at lows; cần education hoặc phân bổ thấp rủi ro hơn."],"answer":"Không mặc định dùng allocation high-risk chỉ vì khách hàng giàu."},{"id":"E05-01","los_ids":["CFA26-09-04-LOS05"],"problem":"Nghĩa vụ 300 triệu sau 3 tháng, reliable cash inflow 100 triệu; liquidity gap?","solution_steps":["Gap cơ bản=300−100=200 triệu.","Dự phòng thêm buffer khi nguồn thu có thể trễ; không chọn asset long lockup cho khoản 200 triệu chắc chắn."],"answer":"Minimum planned liquidity gap 200 triệu trước stress buffer."},{"id":"E05-02","los_ids":["CFA26-09-04-LOS05"],"problem":"Nhà đầu tư có equity employer stock chiếm 70% tài sản.","solution_steps":["Đây là unique concentration/career exposure risk vì thu nhập và portfolio có thể cùng chịu company shock.","IPS nên xem xét diversification plan, trading restrictions và taxes."],"answer":"Giảm concentration phù hợp constraints; không đánh giá riêng lợi suất kỳ vọng cổ phiếu công ty."},{"id":"E06-01","los_ids":["CFA26-09-04-LOS06"],"problem":"Portfolio có 60% equity ETF + 40% balanced fund chứa 50% equity, 50% bond.","solution_steps":["Look-through equity =60%+40%×50%=80%.","Bond exposure=40%×50%=20%.","Không gán toàn bộ balanced fund vào nhóm độc lập nếu cần xem total stock risk."],"answer":"Exposure sau look-through là 80% equity, 20% bond."},{"id":"E06-02","los_ids":["CFA26-09-04-LOS06"],"problem":"Quỹ A dùng equity ETF, quỹ B dùng equity index mutual fund cùng S&P500.","solution_steps":["Hai vehicles khác trading/NAV/fees nhưng largely same underlying equity asset class.","Nắm cả hai không tự tạo diversification asset-class mạnh."],"answer":"Cần xem holdings/factors, không đếm vehicles để đánh giá phân tán rủi ro."},{"id":"E07-01","los_ids":["CFA26-09-04-LOS07"],"problem":"Portfolio 1 tỷ, SAA equity60%/bond40%, nay equity700, bond300. Rebalance?","solution_steps":["Target values equity600, bond400 triệu.","Bán equity100, mua bond100 triệu; kiểm tra taxes và transaction fees."],"answer":"Chuyển 100 triệu từ equity sang bond để khôi phục 60/40."},{"id":"E07-02","los_ids":["CFA26-09-04-LOS07"],"problem":"IPS cấm leverage, optimizer đề xuất 130% equity và −30% cash.","solution_steps":["Tổng net weight 100% nhưng gross exposure 130% equity dùng borrowing.","Vi phạm no leverage constraint; phải tối ưu lại với legal/margin bounds."],"answer":"Không triển khai allocation đề xuất; áp constraints của IPS."},{"id":"E08-01","los_ids":["CFA26-09-04-LOS08"],"problem":"IPS loại trừ sector coal; active manager muốn mua coal stock vì P/E rất thấp.","solution_steps":["Xem exclusion là binding mandate constraint, dù expected return hấp dẫn.","Nếu muốn thay đổi phạm vi, phải xin sửa IPS trước, không override tùy ý."],"answer":"Không mua coal stock khi IPS exclusion đang hiệu lực."},{"id":"E08-02","los_ids":["CFA26-09-04-LOS08"],"problem":"Portfolio impact mandate muốn giảm CO₂ financed emissions 20% so baseline100 tấn.","solution_steps":["Target emissions=100×(1−20%)=80 tấn trong cùng phương pháp measurement.","Phải xác định data quality, scopes, boundary và liệu reduction do hoạt động thực hay do asset sales."],"answer":"Target 80 tấn theo giả định, cần phương pháp đo tác động nhất quán."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-04-LOS01"],"stem":"Lợi ích chính của IPS viết rõ?","options":["Bảo đảm lợi suất dương","Tiêu chuẩn kỷ luật và trách nhiệm ra quyết định","Loại bỏ mọi rủi ro thị trường"],"correct_option":1,"explanation":"IPS định nghĩa objectives, constraints và benchmark có thể kiểm tra; không là bảo đảm sinh lời."},{"id":"Q01-02","los_ids":["CFA26-09-04-LOS01"],"stem":"Nên sửa IPS lúc nào?","options":["Bất cứ khi nào cổ phiếu giảm 1%","Chỉ vào đúng ngày ký hợp đồng đầu tiên","Khi mục tiêu, nghĩa vụ hay constraints của client thay đổi quan trọng"],"correct_option":2,"explanation":"Thay đổi hoàn cảnh trọng yếu hoặc kỳ đánh giá định kỳ là lý do sửa IPS; biến động thường ngày không tự động thay objective."},{"id":"Q01-03","los_ids":["CFA26-09-04-LOS01"],"stem":"Một benchmark IPS phù hợp cần được lựa chọn?","options":["Trước kỳ đánh giá và phù hợp mục tiêu/rủi ro","Sau khi biết kết quả đầu tư","Chỉ theo chỉ số có lợi suất thấp nhất"],"correct_option":0,"explanation":"Benchmark định trước và phù hợp mandate giúp đánh giá performance công bằng và tránh cherry-picking."},{"id":"Q02-01","los_ids":["CFA26-09-04-LOS02"],"stem":"Mục tiêu và ràng buộc trong IPS gồm?","options":["Chỉ giả định macro","Risk/return objectives và L-T-L-L-U constraints","Chỉ bảng giá cổ phiếu"],"correct_option":1,"explanation":"IPS đặt mục tiêu và constraints về liquidity, time, tax, legal, unique; không phải danh sách mã đầu tư."},{"id":"Q02-02","los_ids":["CFA26-09-04-LOS02"],"stem":"Real target3%, inflation2%, nominal compounded target?","options":["1,0%","3,0%","5,06%"],"correct_option":2,"explanation":"(1,03×1,02)−1=5,06%, khác phép cộng chính xác do hiệu ứng compounding."},{"id":"Q02-03","los_ids":["CFA26-09-04-LOS02"],"stem":"Bộ phận quyết định benchmark nên được ghi ở đâu?","options":["IPS/mandate trước kỳ đánh giá","Chỉ báo cáo sau khi có return","Không cần văn bản"],"correct_option":0,"explanation":"Benchmark và trách nhiệm cần thỏa thuận trong IPS để tránh lựa chọn theo kết quả thực tế."},{"id":"Q03-01","los_ids":["CFA26-09-04-LOS03"],"stem":"Required return được xác định chủ yếu từ?","options":["Mức lợi suất lịch sử cao nhất","Nghĩa vụ, nguồn vốn, horizon và mục tiêu của khách hàng","Lãi suất vay margin cao nhất"],"correct_option":1,"explanation":"Required return phụ thuộc dòng tiền và mục tiêu tài chính, khác desired return có thể phi thực tế."},{"id":"Q03-02","los_ids":["CFA26-09-04-LOS03"],"stem":"400 triệu thành 500 triệu sau 5 năm; annual growth rate gần?","options":["25%","6,25%","4,56%"],"correct_option":2,"explanation":"r=(1,25)^(1/5)−1≈0,04564; chia 25% cho 5 chỉ là xấp xỉ thô. Kết quả 25% là tổng mức tăng trong toàn bộ 5 năm, không phải CAGR mỗi năm."},{"id":"Q03-03","los_ids":["CFA26-09-04-LOS03"],"stem":"Tracking error đo?","options":["Biến động active return so benchmark","Rủi ro tín dụng issuer duy nhất","Thuế hoãn lại"],"correct_option":0,"explanation":"Tracking error là standard deviation của return chênh lệch với benchmark, phù hợp relative risk mandates."},{"id":"Q04-01","los_ids":["CFA26-09-04-LOS04"],"stem":"Khách hàng sẵn lòng chịu rủi ro cao nhưng không thể đáp ứng liabilities nếu lỗ. Allocation nên?","options":["Dựa willingness","Dựa khả năng chịu lỗ thấp hơn","Luôn 100% equities"],"correct_option":1,"explanation":"Risk tolerance bị ràng buộc bởi ability khi nó thấp hơn willingness; tránh bỏ lỡ nghĩa vụ thiết yếu."},{"id":"Q04-02","los_ids":["CFA26-09-04-LOS04"],"stem":"Khả năng chịu rủi ro bị ảnh hưởng mạnh nhất bởi?","options":["Màu yêu thích của nhà đầu tư","Ý kiến chuyên gia trên mạng","Cash flows và nghĩa vụ tài chính"],"correct_option":2,"explanation":"Risk capacity đến từ điều kiện tài chính khách quan, khác sở thích chấp nhận rủi ro."},{"id":"Q04-03","los_ids":["CFA26-09-04-LOS04"],"stem":"Client ability cao nhưng willingness thấp, nên?","options":["Điều chỉnh portfolio theo willingness thực tế và tư vấn dần","Bỏ qua thái độ để tối ưu expected return","Vay margin"],"correct_option":0,"explanation":"Willingness quá thấp có thể gây panic selling; IPS cần có mức rủi ro khách hàng có thể giữ trong stress."},{"id":"Q05-01","los_ids":["CFA26-09-04-LOS05"],"stem":"Liquidity constraint thể hiện rõ nhất qua?","options":["Số năm công ty niêm yết","Nhu cầu tiền mặt đúng kỳ","Chỉ risk aversion tâm lý"],"correct_option":1,"explanation":"Cash obligations và khả năng huy động tiền xác định liquidity; không chỉ khác biệt trong expected return."},{"id":"Q05-02","los_ids":["CFA26-09-04-LOS05"],"stem":"Client horizon20 năm nhưng cần 300 triệu sau 1 tháng. Điều nào đúng?","options":["100% private equity khóa 10 năm","Bỏ qua nhu cầu tháng tới","Phải giữ lượng tiền phù hợp khoản chi gần"],"correct_option":2,"explanation":"Nhiều horizon cùng tồn tại; cash need sớm là constraint cứng cho phần tài sản phải thanh toán."},{"id":"Q05-03","los_ids":["CFA26-09-04-LOS05"],"stem":"Concentrated employer stock là ví dụ của?","options":["Unique circumstance và concentration risk","Hurdle rate","Risk-free allocation"],"correct_option":0,"explanation":"Nghề nghiệp và tài sản cùng tập trung ở một issuer tạo correlated risks, cần ghi vào IPS."},{"id":"Q06-01","los_ids":["CFA26-09-04-LOS06"],"stem":"ETF equity và mutual fund equity cùng index nên được xếp?","options":["Bắt buộc là hai asset classes","Thường cùng equity asset class exposure","Một tài sản là risk-free"],"correct_option":1,"explanation":"Investment vehicle khác underlying asset class; phân bổ dựa exposure thực tế để tránh double count."},{"id":"Q06-02","los_ids":["CFA26-09-04-LOS06"],"stem":"60% equity ETF, 40% balanced 50/50; equity exposure sau look-through?","options":["60%","100%","80%"],"correct_option":2,"explanation":"60%+40%×50%=80%; phần còn lại 20% là bond exposure. Đáp án 60% bỏ qua equity trong balanced fund; 100% coi phần bond là equity."},{"id":"Q06-03","los_ids":["CFA26-09-04-LOS06"],"stem":"Nhóm asset class tốt nên?","options":["Có động lực rủi ro tương đồng bên trong và phân biệt với nhóm khác","Mọi tài sản có 0% correlation bắt buộc","Chỉ có lợi suất lịch sử cao"],"correct_option":0,"explanation":"Asset class classification hỗ trợ estimation, diversification và benchmark suitability."},{"id":"Q07-01","los_ids":["CFA26-09-04-LOS07"],"stem":"Strategic asset allocation chủ yếu để?","options":["Thay đổi risk tolerance hàng tuần","Xác định long-term asset class weights theo IPS","Chọn thời điểm mua mỗi cổ phiếu trong ngày"],"correct_option":1,"explanation":"SAA liên kết objectives/constraints với exposures dài hạn; tactical shifts nếu có là lớp quyết định khác."},{"id":"Q07-02","los_ids":["CFA26-09-04-LOS07"],"stem":"Portfolio1 tỷ target60/40, hiện equity700, bond300; giao dịch phục hồi?","options":["Không cần điều chỉnh dù vượt mọi band","Mua equity100","Bán equity100, mua bond100"],"correct_option":2,"explanation":"Target equity600; giảm equity100 và tăng bond100 nếu không có external cashflows."},{"id":"Q07-03","los_ids":["CFA26-09-04-LOS07"],"stem":"Optimizer đề xuất −30% cash trong IPS cấm vay. Điều này?","options":["Không được thực hiện vì borrowing constraint","Tự động khả thi vì weights sum100","Không liên quan IPS"],"correct_option":0,"explanation":"Negative cash weight phản ánh vay vốn trong mô hình đơn giản, vi phạm IPS no-leverage."},{"id":"Q08-01","los_ids":["CFA26-09-04-LOS08"],"stem":"ESG integration có nghĩa?","options":["Chỉ loại mọi doanh nghiệp carbon cao","Đưa ESG factors material vào analysis và portfolio construction","Bảo đảm alpha dương"],"correct_option":1,"explanation":"ESG integration đánh giá factors material cho risk/return, khác exclusionary screening và không bảo đảm performance."},{"id":"Q08-02","los_ids":["CFA26-09-04-LOS08"],"stem":"Client cấm tobacco trong IPS, manager thấy stock hấp dẫn. Nên?","options":["Bỏ IPS vì expected return cao","Mua rồi chỉ báo cáo cuối năm","Tuân thủ IPS, không mua"],"correct_option":2,"explanation":"Binding exclusion trong IPS phải được tuân thủ; cần xin thay đổi mandate trước khi giao dịch."},{"id":"Q08-03","los_ids":["CFA26-09-04-LOS08"],"stem":"Impact investing khác thematic investing chủ yếu ở việc?","options":["Theo đuổi và đo lường kết quả tác động tích cực","Không cần đo tác động","Luôn có tracking error0"],"correct_option":0,"explanation":"Impact mandate yêu cầu intentionality và measurable outcomes, không chỉ sở hữu một lĩnh vực đang được ưa chuộng."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-04-LOS01"],"front":"IPS là thỏa thuận có hệ thống — giải thích và ứng dụng?","back":"Investment Policy Statement ghi rõ objectives, constraints, risk tolerance, benchmark và quy trình review để cả client lẫn manager có chuẩn ra quyết định. Văn bản làm rõ phạm vi discretion, trách nhiệm của các bên và tránh thay đổi theo tâm lý ngắn hạn."},{"id":"C01-02","los_ids":["CFA26-09-04-LOS01"],"front":"Kỷ luật khi thị trường biến động — giải thích và ứng dụng?","back":"Khi giá tài sản giảm sâu, IPS giúp đánh giá xem tổn thất có nằm trong phạm vi risk budget dự kiến và có thay đổi liability/ability không. IPS không cấm thay đổi danh mục, nhưng yêu cầu thay đổi theo quy trình và thông tin khách hàng chứ không phản ứng vội."},{"id":"C01-03","los_ids":["CFA26-09-04-LOS01"],"front":"Đánh giá hiệu quả và accountability — giải thích và ứng dụng?","back":"Benchmark và performance/risk measures được xác định trước tạo tiêu chuẩn đo lường rõ ràng. Không nên chọn benchmark sau khi biết return hoặc dùng ước tính risk tolerance cũ khi hoàn cảnh đã thay đổi."},{"id":"C02-01","los_ids":["CFA26-09-04-LOS02"],"front":"Return và risk objectives — giải thích và ứng dụng?","back":"IPS nêu required/desired return (nominal/real, trước/sau thuế/phí), risk limits theo volatility/drawdown/tracking error và capacity. Mục tiêu return phải khả thi với ràng buộc và phương án allocation."},{"id":"C02-02","los_ids":["CFA26-09-04-LOS02"],"front":"Investment constraints — giải thích và ứng dụng?","back":"Liệt kê liquidity needs, investment horizon, tax considerations, legal/regulatory limits và unique circumstances (L-T-L-L-U). Có thể bổ sung leverage limits, prohibited securities, currency exposure và concentration constraints."},{"id":"C02-03","los_ids":["CFA26-09-04-LOS02"],"front":"Strategic asset allocation và benchmark — giải thích và ứng dụng?","back":"IPS thường quy định target/ranges cho asset classes, benchmark phù hợp, rebalancing thresholds, sử dụng derivatives/illiquid assets và phương pháp risk monitoring. Không nhất thiết nêu từng mã cổ phiếu."},{"id":"C03-01","los_ids":["CFA26-09-04-LOS03"],"front":"Required và desired return — giải thích và ứng dụng?","back":"Required return xuất phát cashflow, liabilities, taxes, inflation, capital preservation; desired return là mức client mong muốn. Nếu desired return vượt mức khả thi với risk tolerance, cần điều chỉnh mục tiêu, đóng góp hoặc thời gian chứ không mặc định tăng leverage."},{"id":"C03-02","los_ids":["CFA26-09-04-LOS03"],"front":"Absolute và relative objectives — giải thích và ứng dụng?","back":"Absolute return target có thể biểu diễn nominal/real return hoặc bảo toàn vốn; relative return target so benchmark, inflation hay liability growth. Thời gian đo lường, gross/net fees và tax basis phải thống nhất."},{"id":"C03-03","los_ids":["CFA26-09-04-LOS03"],"front":"Risk objectives theo tài chính và tâm lý — giải thích và ứng dụng?","back":"Capacity dựa financial ability, liabilities, horizon; willingness dựa psychometric attitudes/experience. Có thể dùng volatility, downside deviation, expected shortfall, tracking error hoặc funded-ratio risk; mỗi thước đo chỉ phản ánh một lát cắt."},{"id":"C04-01","los_ids":["CFA26-09-04-LOS04"],"front":"Ability là năng lực tài chính khách quan — giải thích và ứng dụng?","back":"Xem net worth, employment income, liquidity needs, debt maturity, retirement horizon, liabilities và khả năng bù lỗ từ nguồn khác. Khách hàng nhiều tài sản nhưng tất cả bị ràng buộc cho nghĩa vụ ngắn hạn có capacity thấp hơn vẻ ngoài."},{"id":"C04-02","los_ids":["CFA26-09-04-LOS04"],"front":"Willingness là thái độ tâm lý — giải thích và ứng dụng?","back":"Khai thác kinh nghiệm đầu tư, phản ứng với drawdown, trade-offs giữa return và loss bằng phỏng vấn/scenarios. Mức willingness có thể thay đổi theo market cycle và chịu framing bias; không dùng một câu hỏi cảm tính làm kết luận cuối."},{"id":"C04-03","los_ids":["CFA26-09-04-LOS04"],"front":"Nguyên tắc mức chịu rủi ro thấp hơn — giải thích và ứng dụng?","back":"Nếu willingness rất cao nhưng ability thấp, portfolio phải giới hạn bởi ability để không đe dọa nghĩa vụ. Nếu ability cao nhưng willingness thấp, cố ép allocation mạo hiểm có thể khiến panic selling đúng đáy."},{"id":"C05-01","los_ids":["CFA26-09-04-LOS05"],"front":"Liquidity constraints — giải thích và ứng dụng?","back":"Cash withdrawals, spending needs, emergency buffer và margin calls quyết định phần tài sản cần dễ bán. Quỹ có liabilities thanh toán hàng tháng không nên đặt toàn bộ vào assets khóa rút 5 năm dù expected return hấp dẫn."},{"id":"C05-02","los_ids":["CFA26-09-04-LOS05"],"front":"Time horizon — giải thích và ứng dụng?","back":"Horizons có thể nhiều giai đoạn: accumulation, retirement withdrawals, estate transfer. Kỳ dài hỗ trợ chịu volatility tạm thời nhưng không xóa tail risk; short horizon thường tăng ưu tiên capital preservation và liquidity."},{"id":"C05-03","los_ids":["CFA26-09-04-LOS05"],"front":"Tax constraints — giải thích và ứng dụng?","back":"Xét marginal tax rates, capital gains treatment, tax-deferred accounts, loss harvesting và giao dịch phát sinh thuế. Tax-efficient allocation khác nhau tùy jurisdiction, nên không tự suy thuế suất nếu đề không cung cấp."},{"id":"C06-01","los_ids":["CFA26-09-04-LOS06"],"front":"Asset class phải tương đồng bên trong — giải thích và ứng dụng?","back":"Một asset class nên có risk/return drivers tương đối giống nhau, khác biệt với nhóm khác, đủ lớn và có thể đo/đầu tư/định giá. Phân nhóm theo geography, duration, credit, public/private hoặc economic exposures tùy mandate."},{"id":"C06-02","los_ids":["CFA26-09-04-LOS06"],"front":"Tránh double-counting — giải thích và ứng dụng?","back":"Một quỹ multi-asset không thể vừa tính toàn bộ ở equity vừa toàn bộ ở bond; phải look-through underlying allocations nếu dữ liệu cho phép. Commodity futures khác physical commodities về cash collateral và roll yield."},{"id":"C06-03","los_ids":["CFA26-09-04-LOS06"],"front":"Investability và data — giải thích và ứng dụng?","back":"Asset class cần benchmark tin cậy, liquidity phù hợp, estimates of E(R), volatility, correlation, costs và tax treatments. Tài sản không giao dịch thường xuyên có unsmoothing problem và estimation risk."},{"id":"C07-01","los_ids":["CFA26-09-04-LOS07"],"front":"Strategic asset allocation là quyết định dài hạn — giải thích và ứng dụng?","back":"SAA chuyển goals/constraints thành target weights asset classes phù hợp liquidity, horizon, risk tolerance và required return. Nhiều nghiên cứu cho thấy allocation quan trọng trong quyết định mức rủi ro danh mục, nhưng không bảo đảm outperform benchmark."},{"id":"C07-02","los_ids":["CFA26-09-04-LOS07"],"front":"Tactical và dynamic allocation — giải thích và ứng dụng?","back":"Tactical asset allocation điều chỉnh ngắn hạn quanh SAA dựa valuation/business cycle; dynamic thường điều chỉnh theo market/liability/risk conditions. Các deviations cần risk budgets và giới hạn rõ trong IPS."},{"id":"C07-03","los_ids":["CFA26-09-04-LOS07"],"front":"Diversification và constraints — giải thích và ứng dụng?","back":"Portfolio construction phối hợp expected returns, variances, covariances, turnover, transaction costs, taxes và constraints. Optimization với estimation error có thể tạo corner weights cực đoan; robust methods, rebalancing bands và diversification caps giúp thực thi."},{"id":"C08-01","los_ids":["CFA26-09-04-LOS08"],"front":"ESG as risk/return input — giải thích và ứng dụng?","back":"Environmental, social, governance factors có thể ảnh hưởng cash flows, cost of capital, litigation/transition risk và long-run competitive advantage. Cần xét materiality theo issuer/industry, tránh coi một ESG score duy nhất là toàn bộ phân tích."},{"id":"C08-02","los_ids":["CFA26-09-04-LOS08"],"front":"Negative/exclusionary screening — giải thích và ứng dụng?","back":"Loại sectors/securities không phù hợp values/mandate (ví dụ tobacco) theo lựa chọn client; thay đổi investable universe có thể tăng concentration/tracking error. Không tự coi exclusion tạo alpha dương hay giảm mọi rủi ro."},{"id":"C08-03","los_ids":["CFA26-09-04-LOS08"],"front":"Positive/best-in-class, integration và engagement — giải thích và ứng dụng?","back":"Best-in-class chọn issuers ESG tốt trong nhóm so sánh; ESG integration đưa dữ liệu material vào valuation/portfolio risk; engagement dùng quyền sở hữu để đối thoại/biểu quyết thay đổi governance."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_PDFs"}]);
window.CFA_AUDIT_TOTALS=(function(previous){previous=previous||{};return {...previous,drafted:Math.max(Number(previous.drafted)||0,334),independently_reaudited:Math.max(Number(previous.independently_reaudited)||0,191),scope:"Targeted three-source LOS review; not exhaustive all PDFs"};})(window.CFA_AUDIT_TOTALS);
